import { roundHalfUp } from "./rounding";

export type DecimalError = "empty" | "invalid" | "negative" | "too-large";

export type DecimalResult =
	| { ok: true; value: number }
	| { ok: false; error: DecimalError };

const NUMBER_PATTERN = /^(-?)(\d*)(?:\.(\d*))?$/;

/**
 * Parses decimal text into an integer scaled by 10^decimals, by splitting at
 * the decimal point and padding the fraction. Extra fraction digits are
 * rounded half up (any digit >= 5 in the first dropped position rounds up).
 * Never uses parseFloat or toFixed.
 */
export const parseScaled = (
	text: string,
	decimals: number,
	allowed: { prefix?: string } = {},
): DecimalResult => {
	let cleaned = text.trim().replaceAll(",", "");
	if (allowed.prefix && cleaned.startsWith(allowed.prefix)) {
		cleaned = cleaned.slice(allowed.prefix.length);
	}
	if (cleaned === "") return { ok: false, error: "empty" };
	const match = NUMBER_PATTERN.exec(cleaned);
	if (!match) return { ok: false, error: "invalid" };
	const [, sign, whole = "", fraction = ""] = match;
	if (whole === "" && fraction === "") return { ok: false, error: "invalid" };
	if (sign === "-") return { ok: false, error: "negative" };
	const kept = fraction.slice(0, decimals).padEnd(decimals, "0");
	const digits = `${whole === "" ? "0" : whole}${kept}`;
	let value = Number(digits);
	if (!Number.isSafeInteger(value)) return { ok: false, error: "too-large" };
	const nextDigit = fraction.charAt(decimals);
	if (nextDigit !== "" && nextDigit >= "5") {
		value = roundHalfUp(value * 2 + 1, 2);
		if (!Number.isSafeInteger(value)) return { ok: false, error: "too-large" };
	}
	return { ok: true, value };
};
EOF

